mapper.select:
SELECT t1.device_code as `code`, t1.upload_time, t1.direction, t1.lng, t1.lat, t1.height, t1.speed, t1.address FROM dispatch_device_gps_history t1
and t1.device_code = #{param.code}
and t1.update_time >= #{param.startTime}
and t1.update_time <= #{param.endTime}
order by t1.upload_time desc
